15 EP — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;d&#233;guisement&lt;/a&gt;&lt;/i&gt; (1 EP), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;j&#224;-Vu.html&quot; title=&quot;D&#233;j&#224; vu&quot;&gt;d&#233;j&#224; vu&lt;/a&gt;&lt;/i&gt; (1 EP), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lien-Mental.html&quot; title=&quot;Lien mental&quot;&gt;lien mental&lt;/a&gt;&lt;/i&gt; (1 EP, DD 13), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Manipulation-&#192;-Distance.html&quot; title=&quot;Manipulation &#224; distance&quot;&gt;manipulation &#224; distance&lt;/a&gt;&lt;/i&gt; (0 EP), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ouverturefermeture.html&quot; title=&quot;Ouverture/fermeture&quot;&gt;ouverture/fermeture&lt;/a&gt;&lt;/i&gt; (0 EP), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Son-Imaginaire.html&quot; title=&quot;Son imaginaire&quot;&gt;son imaginaire&lt;/a&gt;&lt;/i&gt; (0 EP), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#233;l&#233;portation.html&quot; title=&quot;T&#233;l&#233;portation&quot;&gt;t&#233;l&#233;portation&lt;/a&gt;&lt;/i&gt; (sur lui-m&#234;me uniquement, 5 EP)
&lt;/div&gt;
